#!/usr/bin/env python3
"""
Unified Product Category Taxonomy Builder
Processes category hierarchies from Amazon, Facebook, and Google Shopping
to create a unified 5-level taxonomy.
"""

import pandas as pd
import re
from collections import defaultdict, Counter
from typing import List, Dict, Set, Tuple
import numpy as np


class CategoryNormalizer:
    """Handles text normalization and standardization for category names."""

    @staticmethod
    def normalize_text(text: str) -> str:
        """Normalize category text for comparison and grouping."""
        if pd.isna(text):
            return ""

        text = str(text).lower().strip()
        text = re.sub(r'\s+', ' ', text)
        text = re.sub(r'[&]', 'and', text)
        text = re.sub(r'[^\w\s-]', '', text)

        replacements = {
            'mens': 'men',
            'womens': 'women',
            'childrens': 'children',
            'kids': 'children',
            'accessories': 'accessory',
            'supplies': 'supply',
            'products': 'product',
            'equipment': 'gear',
        }

        for old, new in replacements.items():
            text = re.sub(r'\b' + old + r'\b', new, text)

        return text.strip()

    @staticmethod
    def create_display_name(texts: List[str], max_words: int = 5) -> str:
        """Create a representative display name from a group of category texts."""
        if not texts:
            return ""

        word_freq = Counter()
        for text in texts:
            words = text.lower().split()
            for word in words:
                if len(word) > 2 and word not in {'and', 'the', 'for', 'with'}:
                    word_freq[word] += 1

        common_words = [word for word, _ in word_freq.most_common(max_words)]

        if not common_words:
            return texts[0].title()

        base_text = max(texts, key=lambda x: sum(1 for w in common_words if w in x.lower()))
        words = base_text.split()

        filtered_words = []
        for word in words[:max_words]:
            if word.lower() in common_words or len(filtered_words) < 2:
                filtered_words.append(word.title())

        return ' | '.join(filtered_words[:max_words])

    @staticmethod
    def word_overlap(text1: str, text2: str) -> float:
        """Calculate word overlap percentage between two texts."""
        words1 = set(CategoryNormalizer.normalize_text(text1).split())
        words2 = set(CategoryNormalizer.normalize_text(text2).split())

        if not words1 or not words2:
            return 0.0

        intersection = len(words1 & words2)
        union = len(words1 | words2)

        return intersection / union if union > 0 else 0.0


class TaxonomyBuilder:
    """Builds unified taxonomy from multiple category sources."""

    def __init__(self):
        self.normalizer = CategoryNormalizer()
        self.all_categories = []
        self.source_mapping = {}

    def load_data(self, amazon_path: str, fb_path: str, google_path: str):
        """Load category data from all three sources."""
        print("Loading data from all sources...")

        amazon_df = pd.read_csv(amazon_path)
        amazon_df['source'] = 'amazon'

        fb_df = pd.read_csv(fb_path)
        fb_df['source'] = 'facebook'

        google_df = pd.read_csv(google_path)
        google_df['source'] = 'google'

        for df in [amazon_df, fb_df, google_df]:
            for _, row in df.iterrows():
                category_path = row['category_path']
                source = row['source']

                parts = [p.strip() for p in re.split(r'\s*>\s*', str(category_path))]
                parts = [p for p in parts if p]

                if parts:
                    self.all_categories.append({
                        'source': source,
                        'original_path': category_path,
                        'parts': parts,
                        'depth': len(parts)
                    })

        print(f"Loaded {len(self.all_categories)} total categories")
        print(f"  Amazon: {sum(1 for c in self.all_categories if c['source'] == 'amazon')}")
        print(f"  Facebook: {sum(1 for c in self.all_categories if c['source'] == 'facebook')}")
        print(f"  Google: {sum(1 for c in self.all_categories if c['source'] == 'google')}")

    def build_hierarchy(self) -> Dict:
        """Build the unified 5-level hierarchy."""
        print("\nBuilding unified hierarchy...")

        level_categories = defaultdict(lambda: defaultdict(list))

        for cat in self.all_categories:
            for level, part in enumerate(cat['parts'][:5], 1):
                parent_path = tuple(cat['parts'][:level-1]) if level > 1 else ()
                normalized = self.normalizer.normalize_text(part)

                level_categories[level][parent_path].append({
                    'text': part,
                    'normalized': normalized,
                    'source': cat['source'],
                    'full_path': cat['parts'][:level]
                })

        hierarchy = {}

        for level in range(1, 6):
            print(f"\nProcessing level {level}...")
            hierarchy[level] = {}

            for parent_path, categories in level_categories[level].items():
                clusters = self._cluster_categories(categories, level)
                hierarchy[level][parent_path] = clusters

            total_clusters = sum(len(clusters) for clusters in hierarchy[level].values())
            print(f"  Created {total_clusters} unified categories at level {level}")

        return hierarchy

    def _cluster_categories(self, categories: List[Dict], level: int) -> List[Dict]:
        """Cluster similar categories together."""
        if not categories:
            return []

        normalized_groups = defaultdict(list)
        for cat in categories:
            normalized_groups[cat['normalized']].append(cat)

        clusters = []
        processed = set()

        sorted_groups = sorted(normalized_groups.items(), key=lambda x: len(x[1]), reverse=True)

        for norm_key, group in sorted_groups:
            if norm_key in processed:
                continue

            cluster = {
                'members': group,
                'normalized_key': norm_key,
                'sources': [cat['source'] for cat in group]
            }

            for other_norm, other_group in sorted_groups:
                if other_norm == norm_key or other_norm in processed:
                    continue

                if self.normalizer.word_overlap(norm_key, other_norm) > 0.6:
                    cluster['members'].extend(other_group)
                    cluster['sources'].extend([cat['source'] for cat in other_group])
                    processed.add(other_norm)

            clusters.append(cluster)
            processed.add(norm_key)

        for cluster in clusters:
            texts = [m['text'] for m in cluster['members']]
            cluster['display_name'] = self.normalizer.create_display_name(texts)
            cluster['count'] = len(cluster['members'])

        clusters.sort(key=lambda x: x['count'], reverse=True)

        return clusters

    def _balance_hierarchy(self, hierarchy: Dict) -> Dict:
        """Balance the hierarchy to meet size constraints."""
        print("\nBalancing hierarchy...")

        for level in range(1, 6):
            for parent_path, clusters in hierarchy[level].items():
                if len(clusters) > 20:
                    merged = self._merge_small_clusters(clusters, 20)
                    hierarchy[level][parent_path] = merged
                elif len(clusters) < 3 and len(clusters) > 0:
                    hierarchy[level][parent_path] = clusters

        return hierarchy

    def _merge_small_clusters(self, clusters: List[Dict], max_count: int) -> List[Dict]:
        """Merge smaller clusters to meet maximum count constraint."""
        if len(clusters) <= max_count:
            return clusters

        sorted_clusters = sorted(clusters, key=lambda x: x['count'], reverse=True)

        keep_clusters = sorted_clusters[:max_count-1]
        merge_clusters = sorted_clusters[max_count-1:]

        merged = {
            'members': [],
            'sources': [],
            'normalized_key': 'other',
            'count': 0
        }

        for cluster in merge_clusters:
            merged['members'].extend(cluster['members'])
            merged['sources'].extend(cluster['sources'])
            merged['count'] += cluster['count']

        if merged['count'] > 0:
            texts = [m['text'] for m in merged['members']]
            merged['display_name'] = self.normalizer.create_display_name(texts)
            keep_clusters.append(merged)

        return keep_clusters

    def generate_taxonomy_mapping(self, hierarchy: Dict) -> pd.DataFrame:
        """Generate the full taxonomy mapping for all original categories."""
        print("\nGenerating taxonomy mapping...")

        mappings = []

        for cat in self.all_categories:
            mapping = {
                'source': cat['source'],
                'category_path': cat['original_path'],
                'depth': min(cat['depth'], 5),
                'unified_level_1': '',
                'unified_level_2': '',
                'unified_level_3': '',
                'unified_level_4': '',
                'unified_level_5': ''
            }

            for level in range(1, min(cat['depth'] + 1, 6)):
                parent_path = tuple(cat['parts'][:level-1]) if level > 1 else ()

                if parent_path in hierarchy[level]:
                    part_normalized = self.normalizer.normalize_text(cat['parts'][level-1])

                    best_cluster = None
                    best_overlap = 0

                    for cluster in hierarchy[level][parent_path]:
                        for member in cluster['members']:
                            if member['normalized'] == part_normalized:
                                best_cluster = cluster
                                break

                            overlap = self.normalizer.word_overlap(part_normalized, member['normalized'])
                            if overlap > best_overlap:
                                best_overlap = overlap
                                best_cluster = cluster

                        if best_cluster and best_overlap > 0.9:
                            break

                    if best_cluster:
                        mapping[f'unified_level_{level}'] = best_cluster['display_name']

            mappings.append(mapping)

        df = pd.DataFrame(mappings)
        return df

    def generate_hierarchy_catalog(self, hierarchy: Dict) -> pd.DataFrame:
        """Generate the hierarchy catalog with all unique paths."""
        print("\nGenerating hierarchy catalog...")

        paths = set()

        def traverse_hierarchy(level: int, parent_path: tuple, current_unified: list):
            if level > 5:
                paths.add(tuple(current_unified + [''] * (5 - len(current_unified))))
                return

            if parent_path in hierarchy[level]:
                for cluster in hierarchy[level][parent_path]:
                    new_unified = current_unified + [cluster['display_name']]

                    new_parent = parent_path + (cluster['normalized_key'],)
                    traverse_hierarchy(level + 1, new_parent, new_unified)
            else:
                paths.add(tuple(current_unified + [''] * (5 - len(current_unified))))

        traverse_hierarchy(1, (), [])

        catalog_data = []
        for path in sorted(paths):
            catalog_data.append({
                'unified_level_1': path[0],
                'unified_level_2': path[1],
                'unified_level_3': path[2],
                'unified_level_4': path[3],
                'unified_level_5': path[4]
            })

        df = pd.DataFrame(catalog_data)
        df = df[df['unified_level_1'] != '']

        return df


def main():
    """Main execution function."""
    print("=" * 60)
    print("Unified Product Category Taxonomy Builder")
    print("=" * 60)

    builder = TaxonomyBuilder()

    builder.load_data(
        '/root/data/amazon_product_categories.csv',
        '/root/data/fb_product_categories.csv',
        '/root/data/google_shopping_product_categories.csv'
    )

    hierarchy = builder.build_hierarchy()

    hierarchy = builder._balance_hierarchy(hierarchy)

    full_mapping = builder.generate_taxonomy_mapping(hierarchy)

    hierarchy_catalog = builder.generate_hierarchy_catalog(hierarchy)

    print("\n" + "=" * 60)
    print("Saving output files...")
    print("=" * 60)

    full_mapping.to_csv('/root/output/unified_taxonomy_full.csv', index=False)
    print(f"✓ Saved unified_taxonomy_full.csv ({len(full_mapping)} rows)")

