    print(f"✓ Saved unified_taxonomy_hierarchy.csv ({len(hierarchy_catalog)} rows)")

    print("\n" + "=" * 60)
    print("Statistics Summary")
    print("=" * 60)

    print(f"\nSource distribution in full mapping:")
    print(full_mapping['source'].value_counts())

    print(f"\nDepth distribution:")
    print(full_mapping['depth'].value_counts().sort_index())

    print(f"\nLevel 1 categories: {full_mapping['unified_level_1'].nunique()}")

    for level in range(1, 6):
        col = f'unified_level_{level}'
        non_empty = full_mapping[full_mapping[col] != '']
        if len(non_empty) > 0:
            unique_count = non_empty[col].nunique()
            print(f"Level {level} categories: {unique_count}")

    print("\n" + "=" * 60)
    print("Processing complete!")
    print("=" * 60)


if __name__ == "__main__":
    main()

